// --- PREVIOUS PRICE COLOR ---
var role = "PRICE_PREV"; 

try {
    // 1. זיהוי דינמי של המוצר
    var pi = 1; 
    var m = thisComp.name.match(/(\d+)/);
    if (m) { pi = parseInt(m[1], 10); }
    var dataCompName = "PRODUCT_DATA_" + pi;

    // 2. חיבור למערכת העיצוב החדשה
    var ctrl = comp("STYLE_MASTER").layer("STYLE_CTRL");
    var bank = comp("STYLE_MASTER").layer("COLOR_BANK");

    // 3. לוגיקה לבחירת Theme
    var gi = Math.floor((pi - 1) / 4) + 1; 
    var mode = ctrl.effect("Style_Mode")(1).value; 
    var globalT = ctrl.effect("Global_Theme")(1).value;

    // חישוב Group
    var gStart = (gi - 1) * 4 + 1;
    var gName = "Group_" + gStart + "_" + (gStart + 3);
    var groupT = 1;
    try { groupT = ctrl.effect(gName)(1).value; } catch(e) { groupT = globalT; }

    var finalT = 1;
    if (mode == 1) finalT = globalT;
    else if (mode == 2) finalT = groupT;
    else { 
        // בדיקת Override מהדאטה הספציפי
        try {
            var ov = comp(dataCompName).layer("DATA_CTRL").effect("Theme_Override")(1).value; 
            if (ov > 1) finalT = ov - 1; else finalT = groupT;
        } catch(e) { finalT = groupT; }
    }

    // 4. שליפת הצבע מהבנק
    var themes = ['', '2W', 'B', 'P50', 'ALT'];
    var tStr = themes[finalT] || '2W';

    bank.effect(tStr + "_" + role)("Color");

} catch (e) { value; }

