// SALE MAIN PRICE COLOR (Role: PRICE | Logic: Sale Groups)
var role = "PRICE"; // מושך צבע מחיר (למשל 2W_PRICE)
try {
    var ctrl = comp("STYLE_MASTER").layer("STYLE_CTRL");
    var bank = comp("STYLE_MASTER").layer("COLOR_BANK");

    // 1. זיהוי הסלוט (לפי שם הקומפוזיציה: PRICE Sale - 1 -> 1)
    var mySlotNum = 1;
    var m = thisComp.name.match(/(\d+)$/);
    if (m) mySlotNum = parseInt(m[1], 10);

    // 2. חישוב הקבוצה (לפי שלשות: 1-3, 4-6...)
    var saleGroupIndex = Math.floor((mySlotNum - 1) / 3) + 1; 
    var gStart = (saleGroupIndex - 1) * 3 + 1; 
    var gEnd   = saleGroupIndex * 3;           
    var gName  = "Sale_Group_" + gStart + "_" + gEnd; 

    // 3. בדיקת Mode (גלובלי או קבוצתי של סייל)
    var mode = ctrl.effect("Sale_Style_Mode")(1).value; // 1=Global, 2=Group
    var globalT = ctrl.effect("Sale_Global_Theme")(1).value;

    var finalT = globalT; 

    if (mode == 2) { 
        // Group Mode: לוקח מהקבוצה של הסייל
        try { finalT = ctrl.effect(gName)(1).value; } catch(e) { finalT = globalT; }
    } 

    // 4. תרגום לשם הצבע בבנק
    var themes = ['', '2W', 'B', 'P50', 'ALT'];
    var themeName = themes[finalT] || '2W';

    // 5. משיכת הצבע
    // ימשוך למשל: 2W_PRICE, B_PRICE
    bank.effect(themeName + "_" + role)("Color");

} catch (e) {
    [1, 0, 0, 1]; // אדום במקרה שגיאה
}

