// PRICE FILL EXPRESSION (Role: PRICE)
var role = "PRICE";
try {
    var ctrl = comp("STYLE_MASTER").layer("STYLE_CTRL");
    var bank = comp("STYLE_MASTER").layer("COLOR_BANK");

    // זיהוי מספר המוצר מהקומפוזיציה הראשית (PRICE 1 -> 1)
    var pi = 1;
    var m = thisComp.name.match(/(\d+)$/);
    if (m) pi = parseInt(m[1], 10);

    // לוגיקת היררכיה: Global -> Group -> Product
    var gi = Math.floor((pi - 1) / 4) + 1; // חישוב קבוצה (1-4 -> 1)

    // קריאת הגדרות
    var mode = ctrl.effect("Style_Mode")(1).value;       // 1=Global, 2=Group, 3=Product
    var globalT = ctrl.effect("Global_Theme")(1).value;  // Theme גלובלי

    // קריאת Theme של הקבוצה
    var gStart = (gi - 1) * 4 + 1;
    var gName = "Group_" + gStart + "_" + (gStart + 3);
    var groupT = 1;
    try { groupT = ctrl.effect(gName)(1).value; } catch(e) { groupT = globalT; }

    // החלטה סופית על ה-Theme
    var finalT = 1;
    if (mode == 1) { 
        finalT = globalT; 
    } else if (mode == 2) { 
        finalT = groupT; 
    } else {
        // מצב Product: בדיקת Override במוצר הספציפי
        try {
            // שים לב לקו התחתון החשוב: PRODUCT_DATA_
            var ov = comp("PRODUCT_DATA_" + pi).layer("DATA_CTRL").effect("Theme_Override")(1).value;
            // התפריט: 1=NONE, 2=2W...
            if (ov > 1) finalT = ov - 1; 
            else finalT = groupT; // אם NONE, חוזר לקבוצה
        } catch(e) { finalT = groupT; }
    }

    // תרגום לשם הצבע
    var themes = ['', '2W', 'B', 'P50', 'ALT'];
    var tStr = themes[finalT] || '2W';

    // משיכת הצבע
    bank.effect(tStr + "_" + role)("Color");

} catch (e) {
    [1, 0, 1, 1]; // ורוד שגיאה
}

