        if (ov > 1) selectedThemeIndex = ov - 1;

        var globalThemes = ['', '2W', 'B', 'P50', 'ALT'];
        finalThemeName = globalThemes[selectedThemeIndex] || '2W';
        finalBgIndex = ((pi - 1) % 4) + 1;
    }

    var targetLayerName = finalThemeName + '_BG_' + finalBgIndex;
