try {
    var ctrl = comp('STYLE_MASTER').layer('STYLE_CTRL');
    var bank = comp('STYLE_MASTER').layer('COLOR_BANK');

    var pi = 1;
    var m = thisComp.name.match(/(\d+)/);
    if (m) { pi = parseInt(m[1], 10); }

    var dataCompName = 'PRODUCT_DATA_' + pi;
    var dataCtrl = comp(dataCompName).layer('DATA_CTRL');

    var priceSel = 1;
    try { priceSel = dataCtrl.effect('Price_BG_Selection')(1).value; } catch(e){}

    var finalThemeName = '2W';
    var finalBgIndex = 1;

    if (priceSel > 1) {
        var val = priceSel - 2;
        var themes = ['2W', 'B', 'P50', 'ALT'];
        var themeIdx = Math.floor(val / 4);
        finalBgIndex = (val % 4) + 1;
        finalThemeName = themes[themeIdx];
    } else {
        var styleMode = 1;
        try { styleMode = ctrl.effect('Style_Mode')(1).value; } catch(e){}

        var selectedThemeIndex = 1;
        if (styleMode == 1) {
            try { selectedThemeIndex = ctrl.effect('Global_Theme')(1).value; } catch(e) { selectedThemeIndex = 1; }
        } else {
            var groupNum = Math.floor((pi - 1) / 4) + 1;
            var startRange = (groupNum - 1) * 4 + 1;
            var endRange = groupNum * 4;
            var sliderName = 'Group_' + startRange + '_' + endRange;
            try {
                selectedThemeIndex = ctrl.effect(sliderName)(1).value;
            } catch(err) {
                try { selectedThemeIndex = ctrl.effect('Global_Theme')(1).value; } catch(e) { selectedThemeIndex = 1; }
            }
        }

        var ov = 1;
        try { ov = dataCtrl.effect('Theme_Override')(1).value; } catch(e){}
        if (ov > 1) selectedThemeIndex = ov - 1;

        var globalThemes = ['', '2W', 'B', 'P50', 'ALT'];
        finalThemeName = globalThemes[selectedThemeIndex] || '2W';
        finalBgIndex = ((pi - 1) % 4) + 1;
    }

