// SMART BG SIDE (1=Left, 2=Right)
var side = 2; // Default Right
try {
    var dirSel = effect("Price_Direction_Override")(1).value; 
    if (dirSel == 2) side = 2;      // Manual Right
    else if (dirSel == 3) side = 1; // Manual Left
    else {
        // AUTO: לפי הצבע שיצא בסליידר BG_Color
        var c = effect("BG_Color")(1).value;
        if (c == 1 || c == 3) side = 2; // Right
        else side = 1; // Left
    }
} catch(e) { side = 2; }
side;

// SMART BG COLOR (Physical 1-4)
var res = 1; 
try {
    var sel = effect("Price_BG_Selection")(1).value; 

    if (sel > 1) {
        // MANUAL: מחלץ 1-4 מתוך הרשימה הארוכה
        // פריטים 2,6,10,14 -> נותנים 1
        // פריטים 3,7,11,15 -> נותנים 2
        res = ((sel - 2) % 4) + 1;
    } else {
        // AUTO: לפי מספר המוצר (מחזורי)
        var pi = 1; var m = thisComp.name.match(/(\d+)$/); if(m) pi=parseInt(m[1],10);
        res = ((pi - 1) % 4) + 1;
    }
} catch(e) { res = 1; }
res;

var L = thisLayer;
var useAuto = L.effect("Use_Auto_White")("Checkbox") == 1;  // הוסף == 1

if (useAuto) {
  try { 
    var autoW = L.effect("Price_Width_Auto")("Slider");
    (autoW > 0) ? autoW : 2;
  } catch(e) { 
    2; 
  }
} else {
  try {
    L.effect("White_Width_Manual")("Slider");
  } catch(e) {
    2;
  }
}

ctrl = thisLayer;

// 1 = Regular, 2 = Deal
priceType = ctrl.effect("Price_Type")("Menu");

// פונקציה שמחזירה מספר ספרות ממחיר
function digitsFrom(effectName){
  var v = Math.abs(ctrl.effect(effectName)("Slider"));
  var i = Math.floor(v); // מתעלמים מדצימל
  if (isNaN(i) || i <= 0) return 0;
  return i.toString().length;
}

// ב-Deal לוקחים את מחיר העסקה (Y)
// ב-Regular לוקחים את המחיר הרגיל
digits = (priceType == 2)
  ? digitsFrom("Deal Price")
  : digitsFrom("Price Value");

// מיפוי לרוחב
if (digits <= 1) {
  1; // Narrow
} else if (digits == 2) {
  2; // Regular
} else {
  3; // Wide
}

