// SMART POSITION FOR PREV_PRICE (ORIGINAL LOGIC + FIXED DIRECTION)
try {
    var ctrl = thisComp.layer("CTRL");

    // --- 1. חישוב צד הבועה (החלק המתוקן) ---
    var bubbleSide = 2; // Default Right

    // בדיקת כיוון ידני
    var dirOv = 1; 
    try { dirOv = ctrl.effect("Sale_Direction")(1).value; } catch(e){}

    if (dirOv > 1) {
        // ידני: 3=Left, 2=Right
        bubbleSide = (dirOv == 3) ? 1 : 2;
    } else {
        // אוטומטי (לפי סלוט - התיקון שלנו)
        // 1=R, 2=L, 3=R
        var mySlotNum = 1;
        var m = thisComp.name.match(/(\d+)$/);
        if (m) mySlotNum = parseInt(m[1], 10);

        var mod = (mySlotNum - 1) % 3;

        if (mod == 1) bubbleSide = 1; // Left
        else bubbleSide = 2;          // Right
    }

    // --- 2. חישוב מיקום בסיסי (הקוד המקורי שלך מכאן ומטה) ---
    var moveDir = (bubbleSide == 2) ? -1 : 1; // אם הבועה בימין, זוז שמאלה

    var myIndex = 1;
    var idxM = thisLayer.name.match(/(\d+)$/);
    if (idxM) myIndex = parseInt(idxM[1], 10);

    // זיהוי רוחב המספר (1, 2, או יותר ספרות)
    var digits = 1;
    try { 
        var txt = comp("PRICE_REGULAR_" + myIndex).layer("price_main").text.sourceText.toString();
        // ניקוי כל מה שאינו מספר
        var cleanTxt = txt.replace(/[^0-9]/g, "");
        digits = cleanTxt.length;
    } catch(e) {}
    if (digits < 1) digits = 1;

    // --- 3. הדלתות המקוריות שלך ---
    var delta = 0;
    if (bubbleSide == 2) { 
        // בועה בימין
        if (digits == 1) delta = 130;
        else if (digits == 2) delta = 50;
        else delta = -35; 
    } else {
        // בועה בשמאל
        if (digits == 1) delta = -100;
        else if (digits == 2) delta = -30;
        else delta = 60;
    }

    var base = 300; // הבסיס המקורי

    // --- 4. ה-OFFSET הידני ---
    var fineTune = 0;
    try { fineTune = ctrl.effect("Prev_X_SALE_Offset")(1).value; } catch(e){}

    // חישוב סופי (מקורי)
    var finalX = thisComp.width/2 + (moveDir * base) + delta + fineTune;

    [finalX, value[1]];

} catch(e) { value; }

