// =====================
// DEAL PRICE – CENTER ANCHOR
// =====================

ctrl = thisComp.layer("DEAL_CTRL");

LP = thisLayer;
LC = thisComp.layer("deal_currency");
LS = thisComp.layer("deal_separator");
LQ = thisComp.layer("deal_quantity");

// ----- Y קבוע (מדויק אצלך – לא נוגעים יותר) -----
BASE_Y = 340;

// ----- helper -----
function W(L){
  return (L.opacity.value > 0)
    ? L.sourceRectAtTime(time,false).width
    : 0;
}

// ----- widths -----
wP = W(LP);
wC = W(LC);
wS = W(LS);
wQ = W(LQ);

// ----- gaps -----
gPC = (wC>0) ? ctrl.effect("Gap Price → Currency")("Slider") : 0;
gPS = (wS>0) ? ctrl.effect("Gap Price → Separator")("Slider") : 0;
gSQ = (wQ>0) ? ctrl.effect("Gap Separator → Quantity")("Slider") : 0;

// ----- total group width -----
totalW =
  (wC>0 ? wC + gPC : 0) +
  wP +
  (wS>0 ? gPS + wS : 0) +
  (wQ>0 ? gSQ + wQ : 0);

// ----- center -----
centerX = thisComp.width / 2;

// ----- price X (anchor of the whole group) -----
priceX =
  centerX
  - totalW/2
  + (wC>0 ? wC + gPC : 0)
  + wP/2;

// ----- final -----
[priceX, BASE_Y];

