t_ldlaf.code:
var grp = thisLayer;

var mainLayer = thisComp.layer("price_main");
var decLayer  = thisComp.layer("price_decimal");
var curLayer  = thisComp.layer("price_currency");

var unitLayer = null;
try { unitLayer = thisComp.layer("unit_precomp"); } catch(e) {}

function layerBoundsInComp(L){
  var r = L.sourceRectAtTime(time, false);

  // 2 פינות ב-comp space
  var p1 = L.toComp([r.left, r.top]);
  var p2 = L.toComp([r.left + r.width, r.top + r.height]);

  var left   = Math.min(p1[0], p2[0]);
  var right  = Math.max(p1[0], p2[0]);
  return [left, right];
}

var showUnit = comp("PRODUCT_DATA_1").layer("DATA_CTRL").effect("Show_Unit")("Checkbox") == 1;
var bottomLayer = (showUnit && unitLayer) ? unitLayer : curLayer;

var bMain = layerBoundsInComp(mainLayer);
var bDec  = layerBoundsInComp(decLayer);
var bBot  = layerBoundsInComp(bottomLayer);

var groupLeft  = Math.min(bMain[0], bDec[0], bBot[0]);
var groupRight = Math.max(bMain[1], bDec[1], bBot[1]);

