// SMART OPACITY FOR WHITE LAYERS (FIXED DIRECTION LOGIC)
// ========================================================
// הגדרות ספציפיות - חובה לשנות בכל שכבה!
// --------------------------------------------------------
var myWidth = 3;  // 1=צר (Narrow), 2=רגיל (Regular), 3=רחב (Wide)
var mySide = 1;   // 1=שמאל (L), 2=ימין (R)
// ========================================================

try {
    var ctrl = thisComp.layer("CTRL");

    // --- 1. חישוב הצד (Side) ---
    var currentSide = 2; // ברירת מחדל ימין

    // בדיקת כיוון ידני
    var dirOv = 1; 
    try { dirOv = ctrl.effect("Sale_Direction")(1).value; } catch(e){}

    if (dirOv > 1) {
        // ידני: 3=Left, 2=Right
        currentSide = (dirOv == 3) ? 1 : 2;
    } else {
        // אוטומטי (לפי סלוט, בדיוק כמו הרקע)
        var mySlotNum = 1;
        var m = thisComp.name.match(/(\d+)$/);
        if (m) mySlotNum = parseInt(m[1], 10);

        // לוגיקה מתוקנת: 
        // סלוט 1 (שארית 0) -> ימין
        // סלוט 2 (שארית 1) -> שמאל
        // סלוט 3 (שארית 2) -> ימין
        var mod = (mySlotNum - 1) % 3;

        if (mod == 1) currentSide = 1; // Left
        else currentSide = 2;          // Right
    }

    // --- 2. חישוב הרוחב (Width) ---
    var currentWidth = 2; 
    var useAuto = 1;
    try { useAuto = ctrl.effect("Use_Auto_White")(1).value; } catch(e){}

    if (useAuto == 1) {
        // אוטומטי לפי מחיר
        var pIdx = Math.round(ctrl.effect("Product_Index")(1).value);
        var priceVal = 0;
        try {
             priceVal = comp("PRODUCT_DATA_" + pIdx).layer("DATA_CTRL").effect("Price Value")(1).value;
        } catch(e) {
             try { 
                 var txt = comp("PRICE_REGULAR_" + pIdx).layer("price_main").text.sourceText.toString();
                 priceVal = parseFloat(txt.replace(/[^0-9.]/g, ""));
             } catch(e2) {}
        }

        if (priceVal < 10) currentWidth = 1;
        else if (priceVal < 100) currentWidth = 2;
        else currentWidth = 3;

    } else {
        // ידני לפי סליידר
        try { 
            currentWidth = Math.round(ctrl.effect("White_Width_Manual")(1).value); 
            if (currentWidth < 1) currentWidth = 2;
        } catch(e) { currentWidth = 2; }
    }

    // --- 3. בדיקה סופית ---
    // רק אם גם הצד וגם הרוחב מתאימים -> 100%
    (mySide == currentSide && myWidth == currentWidth) ? 100 : 0;

} catch(e) { 
    // במקרה שגיאה, ברירת מחדל רגיל-ימין
    (mySide == 2 && myWidth == 2) ? 100 : 0;
}

