// SALE BG COLOR (Fixed Manual Selection)
try {
    var ctrl = thisComp.layer("CTRL");
    var masterCtrl = comp("STYLE_MASTER").layer("STYLE_CTRL");
    var bank = comp("STYLE_MASTER").layer("COLOR_BANK");

    // זיהוי סלוט
    var mySlotNum = 1;
    var m = thisComp.name.match(/(\d+)$/);
    if (m) mySlotNum = parseInt(m[1], 10);
    var cyclePos = ((mySlotNum - 1) % 3) + 1;

    // --- קביעת הצבע ---
    var sel = 1; 
    try { sel = ctrl.effect("Sale_BG_Selection")(1).value; } catch(e){}

    var targetLayerName = "";

    if (sel > 1) {
        // === ידני (Manual) ===
        // מיפוי התפריט הארוך לשמות בבנק
        // הנחה: הסדר בתפריט הוא:
        // 1=AUTO
        // 2=2W-BG1, 3=2W-BG2, 4=2W-BG3, 5=2W-BG4
        // 6=B-BG1, 7=B-BG2, 8=B-BG3, 9=B-BG4
        // 10=P50-BG1, 11=P50-BG2...

        var val = sel - 2; // מתחילים מ-0 עבור הפריט הראשון אחרי Auto
        var themesOrder = ['2W', 'B', 'P50', 'ALT'];
        var itemsPerTheme = 4; // יש 4 צבעים לכל Theme בתפריט? (BG1..BG4)

        var themeIdx = Math.floor(val / itemsPerTheme);
        var bgIdx = (val % itemsPerTheme) + 1;

        var tName = themesOrder[themeIdx] || '2W';
        targetLayerName = tName + "_BG_" + bgIdx;

    } else {
        // === אוטומטי (AUTO) ===
        var styleMode = masterCtrl.effect("Sale_Style_Mode")(1).value; 
        var globalT = masterCtrl.effect("Sale_Global_Theme")(1).value; 

        var finalT = globalT;
        if (styleMode == 2) { 
             var saleGroupIndex = Math.floor((mySlotNum - 1) / 3) + 1;
             var gStart = (saleGroupIndex - 1) * 3 + 1;
             var gEnd = saleGroupIndex * 3;
             var gName = "Sale_Group_" + gStart + "_" + gEnd;
             try { finalT = masterCtrl.effect(gName)(1).value; } catch(e){}
        }

        var globalThemes = ['', '2W', 'B', 'P50', 'ALT'];
        var finalThemeName = globalThemes[finalT] || '2W';
        var finalBgNum = 1;

        if (finalThemeName == "2W") {
            if (cyclePos == 1) finalBgNum = 1;
            else if (cyclePos == 2) finalBgNum = 2;
            else finalBgNum = 4; 
        } else {
            finalBgNum = cyclePos; 
        }
        targetLayerName = finalThemeName + "_BG_" + finalBgNum;
    }

    bank.effect(targetLayerName)("Color");

} catch(e) {
    [1, 0, 1, 1]; // מג'נטה = השם שהרכבנו לא קיים בבנק
}

