// קוד מתוקן לרקע ראשי - SALES VERSION (FINAL)
var resultColor = [1, 0, 1, 1]; // ברירת מחדל: ורוד (שגיאה)

try {
    var ctrl = comp("STYLE_MASTER").layer("STYLE_CTRL");
    var bank = comp("STYLE_MASTER").layer("COLOR_BANK");

    // 1. קריאת Override - SALES
    var overrideVal = 1;
    try {
        overrideVal = ctrl.effect("Sale_Main_BG_Override")(1).value; 
    } catch(err) { 
        throw "MENU_MISSING"; 
    }

    var selectedIndex = 1;

    // 2. לוגיקה
    if (overrideVal == 1) { 
        // AUTO (Global) - SALES
        selectedIndex = ctrl.effect("Sale_Global_Theme")(1).value;
    } else {
        // MANUAL (Override)
        // התפריט הוא: 1=AUTO, 2=2W, 3=B, 4=P50, 5=ALT
        // המערך הוא: 1=2W, 2=B...
        // אז פריט 2 צריך להיות אינדקס 1
        selectedIndex = overrideVal - 1;
    }

    // 3. תרגום לשם
    var themes = ["ERROR", "2W", "B", "P50", "ALT"];
    var tName = themes[selectedIndex];

    if (!tName) tName = "2W"; // Fallback

    // 4. בניית שם
    var finalName = tName + "_BG_MAIN";

    // 5. משיכת הצבע
    try {
        resultColor = bank.effect(finalName)("Color");
    } catch(e) {
        // צבע כתום אם לא נמצא בבנק
        resultColor = [1, 0.5, 0, 1];
    }

} catch (mainErr) {
    if (mainErr === "MENU_MISSING") {
        resultColor = [0, 1, 0, 1]; // ירוק: תפריט חסר
    } else {
        resultColor = [1, 0, 1, 1]; // ורוד: שגיאה אחרת
    }
}

// השורה האחרונה היא מה שהאקספרשן מחזיר
resultColor;

