t_im4yp3.code:
ctrl = thisLayer;

// 1 = Regular, 2 = Deal
priceType = ctrl.effect("Price_Type")("Menu");

// פונקציה שמחזירה מספר ספרות ממחיר
function digitsFrom(effectName){
  var v = Math.abs(ctrl.effect(effectName)("Slider"));
  var i = Math.floor(v); // מתעלמים מדצימל
  if (isNaN(i) || i <= 0) return 0;
  return i.toString().length;
}

// ב-Deal לוקחים את מחיר העסקה (Y)
// ב-Regular לוקחים את המחיר הרגיל
digits = (priceType == 2)
  ? digitsFrom("Deal Price")
  : digitsFrom("Price Value");

// מיפוי לרוחב
if (digits <= 1) {
  1; // Narrow
} else if (digits == 2) {
  2; // Regular
} else {
  3; // Wide
}

